$readmemh("test_rgb.mem",inputmem.mem,0,5134);
$readmemh("test_expected.mem",expected,0,5250);
$readmemh("test_fa_expected.mem",fa,0,799);
$readmemh("test_fb_expected.mem",fb,0,599);
repeat(10)@(negedge ap_clk);ap_rst_n=1;repeat(10)@(negedge ap_clk);
